def is_kawaii(seq):
    m = max(seq)
    # Condition: if k appears, k-1 appears
    for k in range(2, m + 1):
        if k in seq:
            if (k-1) not in seq:
                return False
    # Condition: first k-1 before last k
    for k in range(2, m + 1):
        if k in seq:
            first_k_minus_1 = seq.index(k-1)
            last_k = len(seq) - 1 - seq[::-1].index(k)
            if first_k_minus_1 > last_k:
                return False
    return True

