    # that contain (1, ..., m) as a subsequence.
    def get_A(n, m):
        if m > n:
            return 0
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        dp[0][0] = 1
        for i in range(1, n + 1):
            # j = 0
            dp[i][0] = dp[i-1][0] * (m - 1)
            # j = 1 to m-1
            for j in range(1, m):
                dp[i][j] = dp[i-1][j] * (m - 1) + dp[i-1][j-1]
            # j = m
            dp[i][m] = dp[i-1][m] * m + dp[i-1][m-1]
        return dp[n][m]

